def test_fill_gaps_rule(grid):
    """Fill gaps on diagonals of sources."""
    from collections import Counter
    rows = len(grid)
    cols = len(grid[0])
    grid_flat = [c for row in grid for c in row]
    bg = Counter(grid_flat).most_common(1)[0][0]

    sources = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != bg]

    result = [row[:] for row in grid]

    # Find all source pairs that are on the same diagonal
    for i in range(len(sources)):
        for j in range(i+1, len(sources)):
            r1, c1 = sources[i]
            r2, c2 = sources[j]

            is_diag, diag_type = grid_meets_diag(r1, c1, r2, c2)

            if is_diag:
                # Get all cells on this diagonal from first to second source
                cells = compute_diagonal_between(r1, c1, r2, c2)

                # Get the values at source positions in this diagonal
                cell_values = {}
                for r, c in cells:
                    if (r, c) in [(r2, c2) for r2, c2 in [(r1, c1), (r2, c2)]]:
                        cell_values[(r, c)] = grid[r][c]
                    else:
                        cell_values[(r, c)] = None

                # Find majority among source values
                value_counts = {}
                for (r, c) in [(r1, c1), (r2, c2)]:
                    v = grid[r][c]
                    value_counts[v] = value_counts.get(v, 0) + 1

                # Find majority value
                majority = max(value_counts, key=value_counts.get)

                # Fill gaps with majority
                for r, c in cells:
                    if grid[r][c] == bg:  # Background cell = gap
                        result[r][c] = majority
                    # else: source cell stays as-is

    return result

