    rows = len(grid)
    cols = len(grid[0])
    grid_flat = [c for row in grid for c in row]
    bg = Counter(grid_flat).most_common(1)[0][0]

    result = [row[:] for row in grid]
    sources = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != bg]

    main_diagonals = {}
    anti_diagonals = {}
    all_diags = set()

    for r, c, val in sources:
        md = r-c
        all_diags.add(md)
        if md not in main_diagonals:
            main_diagonals[md] = []
        main_diagonals[md].append((r, c, val))

        ad = r+c
        all_diags.add(ad)
        if ad not in anti_diagonals:
            anti_diagonals[ad] = []
        anti_diagonals[ad].append((r, c, val))

    def apply_directions(r0, c0, dr, dc, val):
        r, c = r0 + dr, c0 + dc
        while 0 <= r < rows and 0 <= c < cols:
            if grid[r][c] == bg:
                result[r][c] = val
            elif grid[r][c] != bg:
                break
            r += dr
            c += dc

    # Process main diagonals
    for mdr, sources_m in main_diagonals.items():
        if len(sources_m) == 1:
            # Single source: extend in both directions
            apply_directions(sources_m[0][0], sources_m[0][1], -1, -1, sources_m[0][2])
            apply_directions(sources_m[0][0], sources_m[0][1], 1, 1, sources_m[0][2])
        else:
            # Multiple sources: extend only between first and second
            for i in range(len(sources_m)):
                for j in range(i+1, len(sources_m)):
                    r1, c1, v1 = sources_m[i]
                    r2, c2, v2 = sources_m[j]
                    if r2 > r1:
                        apply_directions(r1, c1, 1, 1, v1)
                    elif r2 < r1:
                        apply_directions(r1, c1, -1, -1, v1)

    # Process anti diagonals
    for adr, sources_a in anti_diagonals.items():
        if len(sources_a) == 1:
            apply_directions(sources_a[0][0], sources_a[0][1], -1, 1, sources_a[0][2])
            apply_directions(sources_a[0][0], sources_a[0][1], 1, -1, sources_a[0][2])
        else:
            for i in range(len(sources_a)):
                for j in range(i+1, len(sources_a)):
                    r1, c1, v1 = sources_a[i]
                    r2, c2, v2 = sources_a[j]
                    if r2 > r1:
                        apply_directions(r1, c1, 1, -1, v1)
                    elif r2 < r1:
                        apply_directions(r1, c1, -1, 1, v1)

    return result

