def test_diagonal_extension_v2(grid):
    rows = len(grid)
    cols = len(grid[0])

    if rows == 0:
        return grid

    # Find background color
    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    # Create output (copy input)
    result = [row[:] for row in grid]

    # Find sources (non-background cells)
    sources = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != bg]

    # Group sources by diagonal
    main_diagonals = {}   # key: r-c, value: list of (r, c, val)
    anti_diagonals = {}   # key: r+c, value: list of (r, c, val)

    for r, c, val in sources:
        md = r - c
        ad = r + c
        if md not in main_diagonals:
            main_diagonals[md] = []
        main_diagonals[md].append((r, c, val))
        if ad not in anti_diagonals:
            anti_diagonals[ad] = []
        anti_diagonals[ad].append((r, c, val))

    def fill_between_diag(sources_list, md):
        """Fill between consecutive sources on same diagonal, direction depends on md"""
        if len(sources_list) <= 1:
            return

        # Sort by row
        sources_list_sorted = sorted(sources_list, key=lambda x: x[0])

        for i in range(len(sources_list_sorted)):
            for j in range(i+1, len(sources_list_sorted)):
                r1, c1, v1 = sources_list_sorted[i]
                r2, c2, v2 = sources_list_sorted[j]

                # Determine fill direction based on main diagonal
                if r2 > r1:
                    r, c = r1 + 1, c1 + 1
                    while (r, c) != (r2, c2):
                        if grid[r][c] == bg:
                            result[r][c] = v1
                        r += 1
                        c += 1
                else:
                    r, c = r1 - 1, c1 - 1
                    while (r, c) != (r2, c2):
                        if grid[r][c] == bg:
                            result[r][c] = v1
                        r -= 1
                        c -= 1

    def fill_between_anti(sources_list, ad):
        """Fill between consecutive sources on same anti-diagonal"""
        if len(sources_list) <= 1:
            return

        sources_list_sorted = sorted(sources_list, key=lambda x: x[0])

        for i in range(len(sources_list_sorted)):
            for j in range(i+1, len(sources_list_sorted)):
                r1, c1, v1 = sources_list_sorted[i]
                r2, c2, v2 = sources_list_sorted[j]

                # Fill between in anti-diagonal direction (-1,+1)
                r, c = r1 - 1, c1 + 1
                while (r, c) != (r2, c2):
                    if grid[r][c] == bg:
                        result[r][c] = v1
                    r -= 1
                    c += 1

    def fill_outward_md(r, c, val):
        """Fill outward in main diagonal directions from single source"""
        # Down-right
        r, c = r + 1, c + 1
        while 0 <= r < rows and 0 <= c < cols:
            if grid[r][c] == bg:
                result[r][c] = val
            else:
                break
            r += 1
            c += 1
        # Up-left
        r, c = r - 1, c - 1
        while 0 <= r < rows and 0 <= c < cols:
            if grid[r][c] == bg:
                result[r][c] = val
            else:
                break
            r -= 1
            c -= 1

    def fill_outward_ad(r, c, val):
        """Fill outward in anti-diagonal directions from single source (only down-right)"""
        r, c = r + 1, c - 1
        while 0 <= r < rows and 0 <= c < cols:
            if grid[r][c] == bg:
                result[r][c] = val
            else:
                break
            r += 1
            c -= 1

    # Process main diagonals
    for md, src_list in main_diagonals.items():
        if len(src_list) == 1:
            r, c, val = src_list[0]
            fill_outward_md(r, c, val)
        else:
            fill_between_diag(list(src_list), md)

    # Process anti diagonals
    for ad, src_list in anti_diagonals.items():
        if len(src_list) == 1:
            r, c, val = src_list[0]
            fill_outward_ad(r, c, val)
        else:
            fill_between_anti(list(src_list), ad)

    return result

