def test_diagonal_extension_v3(grid):
    rows = len(grid)
    cols = len(grid[0])

    if rows == 0:
        return grid

    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    result = [row[:] for row in grid]
    sources = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != bg]

    # Group sources by diagonal type
    main_diagonals = {}
    anti_diagonals = {}

    for r, c, val in sources:
        md = r - c
        ad = r + c
        if md not in main_diagonals:
            main_diagonals[md] = []
        main_diagonals[md].append((r, c, val))
        if ad not in anti_diagonals:
            anti_diagonals[ad] = []
        anti_diagonals[ad].append((r, c, val))

    # Helper to extend along main diagonal
    def extend_md(r, c, dr, dc):
        r2, c2 = r + dr, c + dc
        while 0 <= r2 < rows and 0 <= c2 < cols:
            if grid[r2][c2] == bg:
                result[r2][c2] = grid[r][c]
            else:
                break
            r2 += dr
            c2 += dc

    # Helper to extend along anti-diagonal  
    def extend_ad(r, c, dr, dc):
        r2, c2 = r + dr, c + dc
        while 0 <= r2 < rows and 0 <= c2 < cols:
            if grid[r2][c2] == bg:
                result[r2][c2] = grid[r][c]
            else:
                break
            r2 += dr
            c2 += dc

    # Process main diagonals
    for md, src_list in main_diagonals.items():
        if len(src_list) >= 2:
            # Multiple sources, fill between them
            src_list_sorted = sorted(src_list, key=lambda x: x[0])
            for i in range(len(src_list_sorted)):
                for j in range(i+1, len(src_list_sorted)):
                    r1, c1, v1 = src_list_sorted[i]
                    r2, c2, v2 = src_list_sorted[j]
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    for k in range(len(src_list_sorted) - 1):
                        r_curr, c_curr, v_curr = src_list_sorted[k]
                        r_prev, c_prev, v_prev = src_list_sorted[k] if k > 0 else src_list_sorted[i]

                        if (k == 0):
                            # From first source to next
                            r_fill, c_fill = r1 + dr, c1 + dc
                        else:
                            r_curr, c_curr, v_curr = src_list_sorted[k]
                            r_prev, c_prev, v_prev = src_list_sorted[k - 1]
                            r_fill, c_fill = r_prev + dr, c_prev + dc

                        while (r_fill, c_fill) != (r_curr, c_curr):
                            if grid[r_fill][c_fill] == bg:
                                result[r_fill][c_fill] = v_curr
                            r_fill += dr
                            c_fill += dc
        else:
            # Single source, extend outward - use both diagonal types
            src = src_list[0]
            r, c, val = src

            # Extend along main diagonal in both directions
            extend_md(r, c, -1, -1)
            extend_md(r, c, 1, 1)

            # Also extend along anti-diagonal in both directions
            extend_ad(r, c, -1, 1)
            extend_ad(r, c, 1, -1)

    # Process anti diagonals
    for ad, src_list in anti_diagonals.items():
        if len(src_list) >= 2:
            # Multiple sources, fill between them
            src_list_sorted = sorted(src_list, key=lambda x: x[0])
            for i in range(len(src_list_sorted)):
                for j in range(i+1, len(src_list_sorted)):
                    r1, c1, v1 = src_list_sorted[i]
                    r2, c2, v2 = src_list_sorted[j]
                    dr = -1 if r2 > r1 else 1  # anti-diag: dc opposite to dr
                    dc = 1 if c2 > c1 else -1

                    for k in range(len(src_list_sorted)):
                        if k == 0:
                            r_fill, c_fill = r1 + dr, c1 + dc
                        else:
                            r_fill, c_fill = src_list_sorted[k - 1][0] + dr, src_list_sorted[k - 1][1] + dc

                        r_curr, c_curr, v_curr = src_list_sorted[k]
                        while (r_fill, c_fill) != (r_curr, c_curr):
                            if grid[r_fill][c_fill] == bg:
                                result[r_fill][c_fill] = v_curr
                            r_fill += dr
                            c_fill += dc
        else:
            # Single source, extend outward
            src = src_list[0]
            r, c, val = src
            extend_ad(r, c, -1, 1)
            extend_ad(r, c, 1, -1)

    return result

