            r, c, val = src_list[0]
            extend_md_single(r, c, val)
        elif len(src_list) >= 2:
            src_list_sorted = sorted(src_list, key=lambda x: x[0])
            for i in range(len(src_list_sorted)):
                for j in range(i+1, len(src_list_sorted)):
                    r1, c1, v1 = src_list_sorted[i]
                    r2, c2, v2 = src_list_sorted[j]
                    fill_md_between(r1, c1, v1, r2, c2)

    # Anti diagonals: ONLY fill between (contiguous same value sources)
    # Sort anti-diagonal sources and fill only between adjacent sources of SAME value
    for ad, src_list in anti_diagonals.items():
        if len(src_list) < 2:
            continue
        src_list_sorted = sorted(src_list, key=lambda x: x[0])
        for i in range(len(src_list_sorted)):
            for j in range(i+1, len(src_list_sorted)):
                r1, c1, v1 = src_list_sorted[i]
                r2, c2, v2 = src_list_sorted[j]
                # Skip if there's a different value source in between
                fill_ad_same_values(adjacents)

    return result

def test_diagonal_extension_v12b(grid):
    rows = len(grid)
    cols = len(grid[0])

    if rows == 0:
        return grid

    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    bg = Counter(all_cells).most_common(1)[0][0]

    result = [row[:] for row in grid]
    sources = [(r, c, grid[r][c]) for r in range(rows) for c in range(cols) if grid[r][c] != bg]

    def extend_md_single(r, c, val):
        r2, c2 = r - 1, c - 1
        while 0 <= r2 < rows and 0 <= c2 < cols:
            if grid[r2][c2] == bg:
                result[r2][c2] = val
            else:
                break
            r2 -= 1
            c2 -= 1
        r2, c2 = r + 1, c + 1
        while 0 <= r2 < rows and 0 <= c2 < cols:
            if grid[r2][c2] == bg:
                result[r2][c2] = val
            else:
                break
            r2 += 1
            c2 += 1

    def fill_md_between(r1, c1, v1, r2, c2):
        r, c = r1 + 1, c1 + 1
        while (r, c) != (r2, c2):
            if grid[r][c] == bg:
                result[r][c] = v1
            r += 1
            c += 1

    def fill_ad_between_outermost(r1, c1, v1, r2, c2):
        r, c = r1 + 1, c1 - 1
        while (r, c) != (r2, c2):
            if grid[r][c] == bg:
                result[r][c] = v1
            r += 1
            c -= 1

    main_diagonals = {}
    anti_diagonals = {}
    for r, c, val in sources:
        md = r - c
        ad = r + c
        if md not in main_diagonals:
            main_diagonals[md] = []
        main_diagonals[md].append((r, c, val))
        if ad not in anti_diagonals:
            anti_diagonals[ad] = []
        anti_diagonals[ad].append((r, c, val))

    # Main diagonals: single extends, multiple fills between all pairs
    for md, src_list in main_diagonals.items():
        if len(src_list) == 1:
            r, c, val = src_list[0]
            extend_md_single(r, c, val)
        elif len(src_list) >= 2:
            src_list_sorted = sorted(src_list, key=lambda x: x[0])
            for i in range(len(src_list_sorted)):
                for j in range(i+1, len(src_list_sorted)):
                    r1, c1, v1 = src_list_sorted[i]
                    r2, c2, v2 = src_list_sorted[j]
                    fill_md_between(r1, c1, v1, r2, c2)

    # Anti diagonals: fill between outermost sources (ignoring intermediate)
    for ad, src_list in anti_diagonals.items():
        if len(src_list) < 2:
            continue
        src_list_sorted = sorted(src_list, key=lambda x: x[0])
        r1, c1, v1 = src_list_sorted[0]  # outermost/bottom-most
        r2, c2, v2 = src_list_sorted[-1]  # top-most (lowest r)
        fill_ad_between_outermost(r1, c1, v1, r2, c2)

    return result

